@Component
public class RedMetricsInterceptor implements HandlerInterceptor {
    private final MeterRegistry registry;

    public RedMetricsInterceptor(MeterRegistry registry) {
        this.registry = registry;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        request.setAttribute("startTime", System.nanoTime());
        registry.counter("http.server.requests.rate", "uri", request.getRequestURI()).increment();
        return true;
    }

    @Override
    public void afterCompletion(HttpServletRequest request, HttpServletResponse response, Object handler, Exception ex) {
        long startTime = (Long) request.getAttribute("startTime");
        long duration = System.nanoTime() - startTime;

        registry.timer("http.server.requests.duration", "uri", request.getRequestURI())
                .record(duration, TimeUnit.NANOSECONDS);

        if (ex != null || response.getStatus() >= 500) {
            registry.counter("http.server.requests.errors", "uri", request.getRequestURI(), "status", String.valueOf(response.getStatus())).increment();
        }
    }
}
